background.js (service worker)
```js
// background.js
// Stores inferred profile and exposes APIs to content scripts

const DEFAULT_RULES = {
  // Example multipliers (replace with your business logic)
  gender: { male: 1.0, female: 1.05, unknown: 1.02 },
  income_class: { low: 0.95, mid: 1.00, high: 1.10 },
  ethnicity: { asian: 1.00, white: 1.02, black: 1.03, hispanic: 1.01, unknown: 1.00 }
};

chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({ profile: null, rules: DEFAULT_RULES });
});

// Message handler
chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === 'storeProfileSignals') {
    // msg.payload might include: { name, postalCode, amazonProfileUrl, consent: true }
    inferAttributes(msg.payload).then(attrs => {
      chrome.storage.local.set({ profile: attrs });
      sendResponse({ ok: true, attrs });
    });
    return true; // indicate async response
  }

  if (msg.type === 'getProfile') {
    chrome.storage.local.get(['profile', 'rules'], (data) => {
      sendResponse({ profile: data.profile || null, rules: data.rules || DEFAULT_RULES });
    });
    return true;
  }

  if (msg.type === 'setRules') {
    chrome.storage.local.set({ rules: msg.rules }, () => sendResponse({ ok: true }));
    return true;
  }
});

// Inference pipeline: replace callers with real APIs/keys
async function inferAttributes(signals) {
  // signals: { name, postalCode, consent }
  const result = { raw: signals, gender: 'unknown', income_class: 'unknown', ethnicity: 'unknown' };

  if (!signals || !signals.consent) {
    return result;
  }

  try {
    const name = (signals.name || '').split(' ')[0];
    if (name) {
      // Genderize API example
      const gResp = await fetch(`https://api.genderize.io?name=${encodeURIComponent(name)}`);
      if (gResp.ok) {
        const g = await gResp.json();
        if (g.gender) result.gender = g.gender; // male/female
      }
    }

    if (signals.postalCode) {
      // US Census API: replace YOUR_CENSUS_KEY
      const zip = signals.postalCode.substring(0,5);
      const censusKey = 'YOUR_CENSUS_API_KEY';
      const url = `https://api.census.gov/data/2019/acs/acs5/subject?get=NAME,S1903_C03_001E&for=zip%20code%20tabulation%20area:${zip}&key=${censusKey}`;
      const cResp = await fetch(url);
      if (cResp.ok) {
        const json = await cResp.json();
        // json[1][1] would be median household income if present
        const median = parseFloat((json[1] && json[1][1]) || NaN);
        if (!isNaN(median)) {
          if (median < 40000) result.income_class = 'low';
          else if (median < 90000) result.income_class = 'mid';
          else result.income_class = 'high';
        }
      }
    }

    if (signals.name) {
      // Ethnicity inference: placeholder external API
      // Replace endpoint with a real service and API key
      const ethKey = 'YOUR_ETHNICITY_API_KEY';
      const eResp = await fetch(`https://api.ethnicity.example/infer?name=${encodeURIComponent(signals.name)}&key=${ethKey}`);
      if (eResp.ok) {
        const ejson = await eResp.json();
        // Assume ejson.top is top ethnicity label in lowercase
        if (ejson && ejson.top) result.ethnicity = ejson.top;
      }
    }
  } catch (err) {
    console.warn('Inference error', err);
  }

  return result;
}
